/* SettingsToggleRow.css */
.settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(12px, 3vw, 24px);
  padding: clamp(12px, 1.6vw, 16px) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
}

.settings-toggle-row__text {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.settings-toggle-row__label {
  font: inherit;
  font-size: clamp(0.95rem, 0.6rem + 0.8vw, 1.125rem);
  font-weight: 600;
  color: var(--ink);
}

.settings-toggle-row__hint {
  font-size: clamp(0.8rem, 0.55rem + 0.6vw, 0.95rem);
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-toggle-row__switch {
  box-sizing: border-box;
  position: relative;
  flex: none;
  width: 48px;
  height: 28px;
  padding: 0;
  border: 2px solid var(--muted);
  border-radius: 999px;
  background: transparent;
  cursor: pointer;
  font: inherit;
  transition: background-color 160ms ease, border-color 160ms ease;
}

.settings-toggle-row__switch[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
}

.settings-toggle-row__thumb {
  position: absolute;
  top: 50%;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: var(--muted);
  transform: translateY(-50%);
  transition: transform 160ms ease, background-color 160ms ease;
}

.settings-toggle-row__switch[aria-pressed="true"] .settings-toggle-row__thumb {
  background: var(--slide);
  transform: translate(20px, -50%);
}

:root[data-motion="reduce"] .settings-toggle-row__switch,
:root[data-motion="reduce"] .settings-toggle-row__thumb {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .settings-toggle-row__switch,
  .settings-toggle-row__thumb {
    transition: none;
  }
}
